<script setup lang="ts">import type{Job}from'@career-launch/shared';import{formatDeadline}from'@career-launch/shared';import{onMounted,ref}from'vue';import{repository}from'../../services/repository';const items=ref<Job[]>([]);const keyword=ref('');const selected=ref(new Set<string>());async function load(){const term=keyword.value.trim();items.value=(await repository.admin.jobs.list({...term?{keyword:term}:{},city:[],category:[],education:[],sort:'latest',page:1,pageSize:100})).items}async function status(item:Job,next:Job['status']){if(!window.confirm(`确认将“${item.title}”设为${next==='active'?'上架':'下架'}？`))return;await repository.admin.jobs.updateStatus(item.id,next);await load()}onMounted(load)</script>
<template><section><header class="admin-page-head"><div><h1>职位管理</h1><p>录入、核对和调整公开职位状态。</p></div><RouterLink class="cl-primary-button" to="/imports/jobs">Excel 导入</RouterLink></header><div class="admin-toolbar"><input v-model="keyword" aria-label="搜索职位" placeholder="职位或公司" @keyup.enter="load"/><select aria-label="职位状态"><option>全部状态</option><option>在招</option><option>已下架</option><option>已截止</option></select><button class="cl-quiet-button" @click="load">筛选</button><span class="admin-muted">已选择 {{selected.size}} 项</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th><span class="sr-only">选择</span></th><th>职位</th><th>公司</th><th>城市</th><th>截止时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><input type="checkbox" :checked="selected.has(item.id)" aria-label="选择职位" @change="($event.target as HTMLInputElement).checked?selected.add(item.id):selected.delete(item.id)"/></td><td><strong>{{item.title}}</strong><br/><span class="admin-muted">{{item.category}}</span></td><td>{{item.companyName}}</td><td>{{item.city.join('、')}}</td><td>{{formatDeadline(item.deadlineAt)}}</td><td>{{item.status==='active'?'在招':item.status==='offline'?'已下架':'草稿'}}</td><td><button class="admin-link-button">编辑</button><button class="admin-link-button" @click="status(item,item.status==='active'?'offline':'active')">{{item.status==='active'?'下架':'上架'}}</button></td></tr></tbody></table></div></section></template>
